summary=dict(status='collector_complete_pending_independent_review',units=8,input_pages=sum(u['input_page_count'] for u in units),states=sorted(u['state'] for u in units),families=8,original_pdfs=8,fields=sum(u['reference_fields'] for u in units),critical_fields=sum(u['critical_fields'] for u in units),provisional_reference_eligible=sum(u['reference_gate_eligible'] for u in units),independent_review_complete=False,parser_execution_authorized_by_this_artifact=False,new_cloud_parser_outputs_inspected=False,bucket_counts=dict(collections.Counter(u['primary_bucket'] for u in units)),native_extraction={'role':'collector navigation/transcription aid, not scored round2 native arm','library':'pypdf','version':pypdf.__version__,'python':platform.python_version(),'script':'prepare.py','command':'PdfReader page.extract_text() default; exact text retained by page'},rendering={'command':'pdftoppm -scale-to 1600 -png input.pdf page','complete_pages_inspected':22},unresolved=['H06 general box20 calendar days versus target20 working days; critical max-extension field uncertain; no legal resolution.','Independent image-only source review and final experiment-wide configuration/reference freeze required before heldout parsing.','Source collection was not preregistered; final family/reference freeze is prospective only.'])
